window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3a19d25ecc084590"]={"versions": [{"id": "FIG-3a19d25ecc084590", "releases": ["R3.0.7", "R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schematische Konzeptdarstellung mathematischer und tabellarischer Datenstrukturen im Kontext des AUTOSAR Software Component Templates (Kapitel Kalibrierparameter / Calprms). Das Schaubild veranschaulicht grundlegende Kategorien von Kalibrierparametern bzw. Kennfeldern und Stützstellenstrukturen ohne formale UML-Notation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Schaubild umfasst drei voneinander getrennte grafische Entitäten:</p>\n<ul class=\"fig-list\">\n<li>Links: Ein zweidimensionales kartesisches Koordinatensystem mit zwei orthogonalen Pfeilachsen und einem nichtlinearen Funktionsverlauf (Kennlinie bzw. CURVE).</li>\n<li>Mitte: Ein dreidimensionales Koordinatensystem mit drei Achsen und einer schattierten Freiformfläche (Kennfeld bzw. MAP).</li>\n<li>Rechts: Eine eindimensionale Achse mit Pfeilspitze und vier vertikalen Teilstrichen/Intervallmarkierungen (Stützstellenachse bzw. AXIS/COM_AXIS).</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen oder textuelle Bezeichner sind im Schaubild selbst nicht explizit beschriftet.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Repräsentationsmodell für Kalibrierdaten. Es wird kein dynamischer Ablauf oder zeitlicher Sequenzfluss dargestellt; die grafischen Elemente repräsentieren mathematische Abbildungen von Eingangsgrößen auf Ausgangsgrößen bzw. Diskretisierungsstützpunkte zur Laufzeitinterpretation in Software-Komponenten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dient dem konzeptionellen Verständnis der Modellierungsklassen für Kalibrierparameter (wie z. B. CURVE, MAP, COM_AXIS oder STD_AXIS). Software-Architekten und Entwickler müssen die entsprechenden M1-Parameterdefinitionen (ParameterDataPrototype / ApplicationDataType) gemäß den abgebildeten Strukturdimensionen parametrieren und bereitstellen.</p>"}, {"id": "FIG-5d0ebad70a248462", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schematische Konzeptdarstellung mathematischer und tabellarischer Datenstrukturen im Kontext des AUTOSAR Software Component Templates (Kapitel Kalibrierparameter / Calprms). Das Schaubild veranschaulicht grundlegende Kategorien von Kalibrierparametern bzw. Kennfeldern und Stützstellenstrukturen ohne formale UML-Notation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Schaubild umfasst drei voneinander getrennte grafische Entitäten:</p>\n<ul class=\"fig-list\">\n<li>Links: Ein zweidimensionales kartesisches Koordinatensystem mit zwei orthogonalen Pfeilachsen und einem nichtlinearen Funktionsverlauf (Kennlinie bzw. CURVE).</li>\n<li>Mitte: Ein dreidimensionales Koordinatensystem mit drei Achsen und einer schattierten Freiformfläche (Kennfeld bzw. MAP).</li>\n<li>Rechts: Eine eindimensionale Achse mit Pfeilspitze und vier vertikalen Teilstrichen/Intervallmarkierungen (Stützstellenachse bzw. AXIS/COM_AXIS).</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen oder textuelle Bezeichner sind im Schaubild selbst nicht explizit beschriftet.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Repräsentationsmodell für Kalibrierdaten. Es wird kein dynamischer Ablauf oder zeitlicher Sequenzfluss dargestellt; die grafischen Elemente repräsentieren mathematische Abbildungen von Eingangsgrößen auf Ausgangsgrößen bzw. Diskretisierungsstützpunkte zur Laufzeitinterpretation in Software-Komponenten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dient dem konzeptionellen Verständnis der Modellierungsklassen für Kalibrierparameter (wie z. B. CURVE, MAP, COM_AXIS oder STD_AXIS). Software-Architekten und Entwickler müssen die entsprechenden M1-Parameterdefinitionen (ParameterDataPrototype / ApplicationDataType) gemäß den abgebildeten Strukturdimensionen parametrieren und bereitstellen.</p>"}], "trans": [{"from": "FIG-3a19d25ecc084590", "to": "FIG-5d0ebad70a248462", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5d0ebad70a248462", "to": "FIG-3a19d25ecc084590", "fr": "R3.1.5", "tr": "R4.0.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
